```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        // The `subscriptions` store holds the feed list under the key `urls`,
        // one URL per line. Absence is a trap rather than an empty output, so
        // the node never emits a subscription list that lacks `urls`.
        let raw = match state_read::get("urls") {
            Some(s) => s,
            None => panic!("LoadSubscriptions: no urls stored under 'subscriptions'"),
        };

        let urls: Vec<String> = raw
            .lines()
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .map(String::from)
            .collect();

        if urls.is_empty() {
            panic!("LoadSubscriptions: stored subscription list is empty");
        }

        SubscriptionList { urls }
    }
}

export!(Node);
